        settings_update(p.parse_args(rest).action == "install")
        return 0
    if cmd == "_config":
        config_merge()
        return 0
    sys.stderr.write("brain: unknown command %r\n\n" % cmd + USAGE)
    return 2


if __name__ == "__main__":
    try:
        sys.exit(main(sys.argv[1:]))
    except BrainError as e:
