function row(t) {
  const done = t.status === 'done';
  const next = openFollowups(t)[0];
  return el('li', {
    class: 'row' + (t.slug === selected ? ' is-sel' : '') + (done ? ' is-done' : ''),
    tabindex: '0', 'aria-current': t.slug === selected ? 'true' : null, 'data-fk': 'row:' + t.slug,
    onclick: () => select(t.slug),
